WITH lines AS (SELECT id, log_ts, status_code, k, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS k, value) SELECT id, log_ts, k, MAX(status_code) OVER (PARTITION BY k ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS status_code_max_15m, ROUND(status_code / SUM(status_code) OVER (PARTITION BY k), 4) AS status_code_share FROM lines WHERE k NOT IN ('version', 'region');
